<?php session_start();if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}require_once __DIR__.'/../config/db.php';if(!$pdo)die('Baza sozlanmagan.');$rows=$pdo->query('SELECT r.*,t.title FROM test_results r JOIN online_tests t ON t.id=r.test_id ORDER BY r.created_at DESC')->fetchAll();function hr($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} ?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test natijalari</title><link rel="stylesheet" href="../assets/css/style.css?v=8"></head><body class="dashboard-body"><header class="site-header"><a class="brand" href="dashboard.php"><span class="brand-mark">A</span><span>ALGORITM<small>Administrator</small></span></a><nav><a href="dashboard.php">Panel</a><a href="tests.php">Testlar boshqaruvi</a><a class="nav-cta" href="logout.php">Chiqish</a></nav></header><main class="dashboard"><div class="dashboard-title"><div><span class="eyebrow">NATIJALAR</span><h1>Test natijalari</h1><p>O‘quvchilarning test natijalari va foiz ko‘rsatkichlari.</p></div><a class="button primary" href="tests.php">Testlarni boshqarish</a></div><section class="table-card"><div class="table-scroll"><table><thead><tr><th>O‘quvchi</th><th>Telefon</th><th>Test</th><th>Natija</th><th>Foiz</th><th>Sana</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=hr($r['full_name'])?></strong></td><td><?=hr($r['phone'])?></td><td><?=hr($r['title'])?></td><td><?=$r['correct_answers']?> / <?=$r['total_questions']?></td><td><strong><?=number_format((float)$r['percentage'],2)?>%</strong></td><td><?=hr($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Hozircha test natijalari yo‘q.</td></tr><?php endif;?></tbody></table></div></section></main><script src="../assets/js/theme.js?v=8"></script></body></html>
